    kind: 'sentence',
    label: null,
    speaker: null,
    text: "There are water pipes running through that back wall, so we can't drill where the cabinets are supposed to go.",
    start_sec: 16.62,
    end_sec: 22.16,
    duration_sec: 5.54,
    text_source: 'script_excel',
