    clip_audio:
      'audio_split/job-8004782d-87b7-415e-a797-95d917b6ef7a/job-8004782d-87b7-415e-a797-95d917b6ef7a_s06.mp3',
    kind: 'sentence',
    label: null,
    speaker: null,
    text: "Unfortunately, we'd have to bring in a plumber for two additional days, and your current budget doesn't cover that.",
    start_sec: 26.48,
    end_sec: 32.96,
    duration_sec: 6.48,
    text_source: 'script_excel',
